--
-- Wygenerowane z analizy starego projektu kgd-group-deweloper:
--   - UI/zachowanie: src/components/templates/rudava-park/**
--   - Treść:         src/data/pages/inwestycja/rudava-park/{index,historia-cen/index,polityka-prywatnosci/index}.json
--
-- Różnice względem starego projektu (patrz AGENTS.md — brak zewnętrznego API):
--   - Apartaments.fields.apartments — realne ceny/statusy/metraże (24 lokale
--     M1A..M12B + 24 osobne miejsca postojowe MP), przekazane ręcznie przez
--     użytkownika 2026-09-04. Zdjęcia poszczególnych lokali (images: [])
--     nadal do uzupełnienia w panelu /admin — bez nich kolumna "Szczegóły"
--     pokazuje "Brak" zamiast linku "Zobacz".
--   - Gallery.fields.images — realne zdjęcia inwestycji (pliki z public/investments/rudava-park/gallery),
--     zamiast fetch() do zewnętrznego CMS.
--   - PriceHistory.fields.rows — wygenerowane z powyższych realnych cen dla
--     WSZYSTKICH pozycji o statusie "Wolny" (wymóg ustawy deweloperskiej —
--     pełny rejestr, nie próbka). Cena m² w dniu rozpoczęcia sprzedaży i jej
--     data to nadal szacunek (brak realnej historii zmian) — do poprawienia
--     w adminie.
--   - Sekcje "PhoneCall" i "Features" nie mają jeszcze komponentu w
--     src/lib/investments/sections.tsx (dokładnie jak w starym projekcie —
--     tam też nie były renderowane, brak wpisu w template.js) — dane zostają
--     zapisane, żeby nic nie zgubić, po prostu się jeszcze nie wyświetlają.
--
-- UPSERT (ON DUPLICATE KEY UPDATE), nie zwykły INSERT — wiersze dla tych 3
-- slugów już istnieją w bazie (poprzedni import), więc zwykły INSERT
-- zderzyłby się z UNIQUE KEY uq_pages_slug i cały import by się nie powiódł.
--
-- Import: mysql -u UZYTKOWNIK -p NAZWA_BAZY < db/inwestycje/rudava-park.sql
-- =============================================================================

INSERT INTO pages (slug, content) VALUES
  ('/inwestycja/rudava-park', '{"slug":"/inwestycja/rudava-park","parent":null,"template":"rudava-park","title":{"value":"Rudava Park – nowoczesne mieszkania na Woli Justowskiej","editable":true,"label":"Tytuł strony"},"updatedAt":"2026-09-03","status":"published","nav":{"label":"Rudava Park","order":1},"seo":{"title":{"value":"Rudava Park – mieszkania na Woli Justowskiej","editable":true,"label":"Tytuł SEO"},"description":{"value":"Mieszkania parterowe z ogródkami oraz dwupoziomowe lokale z antresolą. Nowoczesna architektura i naturalne materiały w zielonej Woli Justowskiej.","editable":true,"label":"Opis SEO"},"keywords":["Rudava Park","mieszkania Wola Justowska","mieszkania z ogródkiem Kraków","lokale dwupoziomowe","nowe mieszkania Kraków"],"canonical":"https://kgd-group.pl/inwestycja/rudava-park","robots":{"index":true,"follow":true},"author":"KGD Group","ogTitle":"Rudava Park – mieszkania na Woli Justowskiej","ogDescription":"Mieszkania parterowe z ogródkami oraz dwupoziomowe lokale z antresolą. Nowoczesna architektura i naturalne materiały w zielonej Woli Justowskiej.","ogImage":"https://kgd-group.pl/assets/images/og-rudava-park.jpg","ogType":"website","ogUrl":"https://kgd-group.pl/inwestycja/rudava-park","ogSiteName":"KGD Group","ogLocale":"pl_PL","twitterCard":"summary_large_image","twitterTitle":"Rudava Park – mieszkania na Woli Justowskiej","twitterDescription":"Mieszkania parterowe z ogródkami oraz dwupoziomowe lokale z antresolą. Nowoczesna architektura i naturalne materiały w zielonej Woli Justowskiej.","twitterImage":"https://kgd-group.pl/assets/images/twitter-rudava-park.jpg","language":"pl","structuredData":[{"type":"WebPage"}]},"sections":[{"id":"phone-call","component":"PhoneCall","type":"section","label":"PhoneCall","fields":{}},{"id":"navbar","component":"Navbar","type":"section","label":"Nawigacja","fields":{"nav":{"value":[{"link":"#","label":"Start"},{"link":"#inwestycja","label":"Inwestycja"},{"link":"#oferta","label":"Oferta"},{"link":"#wizualizacje","label":"Wizualizacje"},{"link":"#lokalizacja","label":"Lokalizacja"},{"link":"/#inwestycje","label":"Deweloper"},{"link":"#kontakt","label":"Kontakt"}],"editable":true,"label":"Linki nawigacji"}}},{"id":"hero","component":"Hero","type":"section","label":"Hero","fields":{"header":{"value":"Rudava Park – przestrzeń, natura i architektura","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Kameralna inwestycja w otoczeniu zieleni, zaprojektowana z myślą o komforcie, prywatności i jakości życia.","editable":true,"label":"Podtytuł"},"buttonLabel":{"value":"Sprawdź dostępność","editable":true,"label":"Etykieta przycisku"}}},{"id":"about-us","component":"AboutUs","type":"section","label":"O inwestycji","fields":{"header":{"value":"O inwestycji","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Rudava Park to zespół 12 domów dwulokalowych położonych w jednej z najbardziej prestiżowych części Krakowa – na Woli Justowskiej. Każdy budynek skrywa  dwa niezależne mieszkania: parterowy lokal o powierzchni ok. 67 m² z wyjściem do prywatnego ogródka oraz dwupoziomowe mieszkanie  ok. 140 m² z antresolą. Projekt łączy funkcjonalne układy z nowoczesną architekturą i naciskiem na codzienny komfort mieszkańców. To propozycja dla osób, które chcą mieszkać blisko centrum, ale na co dzień czuć  spokojny klimat zielonej dzielnicy willowej.","editable":true,"label":"Opis"},"features":{"value":[{"icon":"/investments/rudava-park/icons/icon-map.svg","text":"Prestiżowa lokalizacja Wola Justowska"},{"icon":"/investments/rudava-park/icons/icon-cube.svg","text":"Funkcjonalne układy"},{"icon":"/investments/rudava-park/icons/icon-garden.svg","text":"Naturalne materiały"},{"icon":"/investments/rudava-park/icons/icon-house.svg","text":"Nowoczesne osiedle w zielonym otoczeniu"}],"editable":true,"label":"Cechy inwestycji"}}},{"id":"features","component":"Features","type":"section","label":"Wyjątkowa jakość (sekcja jeszcze bez komponentu — patrz src/lib/investments/sections.tsx)","fields":{"header":{"value":"Wyjątkowa jakość. Sztuka detalu.","editable":true,"label":"Nagłówek"},"subHeader":{"value":"W Rudava Park każdy detal ma znaczenie. Elegancka, czysta architektura łączy się z wysokiej klasy materiałami i precyzją wykonania, tworząc ponadczasową przestrzeń. Aluminiowa stolarka, subtelne balustrady i dopracowane tarasy podkreślają ekskluzywny charakter inwestycji.\\n                        Nowoczesne technologie – pompy ciepła, rekuperacja, ogrzewanie podłogowe oraz przygotowanie pod smart home – zapewniają komfort na co dzień. Całość dopełnia harmonijnie zaprojektowana, zielona przestrzeń wspólna.","editable":true,"label":"Opis"},"item1Header":{"value":"Architektura budynków","editable":true,"label":"Nagłówek 1"},"item1Text":{"value":"Nowoczesną architekturę Rudava Park podkreślają duże aluminiowe przeszklenia, elewacja z tynku z elementami drewna oraz minimalistyczne, płaskie dachy. Przemyślane proporcje budynków i duże okna nadają całości lekkości i podkreślają współczesny charakter inwestycji.","editable":true,"label":"Tekst 1"},"item2Header":{"value":"Nowoczesne technologie i standard","editable":true,"label":"Nagłówek 2"},"item2Text":{"value":"W standardzie przewidziano m.in. pompy ciepła, rekuperację, ogrzewanie podłogowe oraz instalację przygotowaną pod system smart home. Dzięki temu mieszkania są komfortowe w użytkowaniu, a jednocześnie bardziej energooszczędne.","editable":true,"label":"Tekst 2"},"item3Header":{"value":"Mieszkania parterowe z ogrodami","editable":true,"label":"Nagłówek 3"},"item3Text":{"value":"Parterowe mieszkania o powierzchni ok. 67 m² to propozycja dla osób, które chcą mieć własny ogródek  bez konieczności kupowania dużego domu. Funkcjonalny układ z częścią dzienną otwierającą się na taras oraz prywatną strefą sypialni pozwala wygodnie korzystać z przestrzeni.","editable":true,"label":"Tekst 3"},"item4Header":{"value":"Mieszkania dwupoziomowe z antresolą","editable":true,"label":"Nagłówek 4"},"item4Text":{"value":"Dwupoziomowe mieszkania o powierzchni ok. 140 m² z antresolą i tarasem na dachu oferują więcej miejsca i możliwość elastycznej aranżacji. Dolny poziom można przeznaczyć na  salon z aneksem kuchennym i dodatkowy pokój, a górny poziom stworzy prywatną strefę relaksu.","editable":true,"label":"Tekst 4"}}},{"id":"apartaments","component":"Apartaments","type":"section","label":"Dostępne mieszkania","fields":{"header":{"value":"Dostępne mieszkania","editable":true,"label":"Nagłówek"},"subHeader":{"value":"W Rudava Park możesz wybrać między mieszkaniami parterowymi z własnym  ogródkiem a dwupoziomowymi lokalami z antresolą i tarasem na dachu. Poniżej znajdziesz  aktualną listę dostępnych mieszkań wraz z metrażem i układem.","editable":true,"label":"Opis"},"apartments":{"value":[{"unit":"M1A","rooms":"3","area":"63.02","gardenArea":"62","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsce Parkingowe M1 A-MP","rooms":"-","area":"12.50","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M1B","rooms":"5","area":"109.08","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsce Parkingowe M1 B-MP","rooms":"-","area":"12.50","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M2A","rooms":"3","area":"65.71","gardenArea":"160","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsce Parkingowe M2 A-MP","rooms":"-","area":"12.50","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"M2B","rooms":"5","area":"109.08","pricePerM2":"13 900","price":"1 516 212","status":"Wolny","images":[]},{"unit":"Miejsce Parkingowe M2 B-MP","rooms":"-","area":"12.50","pricePerM2":"-","price":"100 000","status":"Wolny","images":[]},{"unit":"M3A","rooms":"3","area":"63.02","gardenArea":"67","pricePerM2":"-","price":"-","status":"Rezerwacja","images":[]},{"unit":"Miejsce Parkingowe M3 A-MP","rooms":"-","area":"12.50","pricePerM2":"-","price":"-","status":"Rezer